function messageAttachment(doc) { const node = document.createElement("section"); node.className = "chat-message is-user"; const preview = doc.text.trim().slice(0, 180); node.innerHTML = `<div class="chat-message-body"><div class="chat-attachment"><strong>📎 ${escapeHtml(doc.name)} · ${doc.text.length.toLocaleString()}자 — 검토 입력에 반영됨</strong><blockquote>${escapeHtml(preview)}${doc.text.trim().length > 180 ? "…" : ""}</blockquote></div></div>`; $("conversation").append(node); $("chat-scroll").scrollTop = $("chat-scroll").scrollHeight; }
