function finishStreamingMessage(stream) { stream.node.classList.remove("is-streaming"); if (!stream.archive) return; if (stream.text.trim()) stream.archive.append(stream.node); else stream.node.remove(); const artifactBlock = document.getElementById("artifact-openers-block"); if (artifactBlock && stream.archive === $("conversation")) $("conversation").append(artifactBlock); }
function toolStatus(status) { return status === "failed" ? ["!", "실패"] : status === "completed" ? ["✓", "완료"] : ["◌", "실행 중"]; }
function beginExecutionHistory() { const history = document.createElement("details"); history.className = "execution-history"; history.open = true; history.innerHTML = "<summary>에이전트 사고 과정 <small>실행 중엔 펼쳐져 있고 끝나면 접힙니다</small></summary><div class=\"execution-history-body\"></div>"; $("conversation").append(history); return { history, body: history.querySelector(".execution-history-body") }; }
function eventDetail(update, fallback) { const parts = []; if (update.tool?.startsWith("agent.") && update.round != null) parts.push(`${update.round}라운드`); if (update.tool === "agent.decision" && update.action) parts.push(`행동 ${update.action}`); parts.push(update.reason || update.text || fallback); if (Array.isArray(update.queries) && update.queries.length) parts.push(`검색어 · ${update.queries.join(" · ")}`); return parts.filter(Boolean).join(" / "); }
function appendToolUpdate(cards, update, target) { const key = `${update.event_id || update.tool}`; let card = cards.get(key); if (!card) { card = document.createElement("article"); card.className = "inline-tool-call is-running"; card.dataset.tool = update.tool; card.innerHTML = `<span class="inline-tool-icon">◌</span><span class="inline-tool-copy"><strong></strong><small></small></span><span class="inline-tool-result">실행 중</span>`; target.append(card); cards.set(key, card); } const [label, fallback] = toolLabels[update.tool] || [update.tool, update.code || "실행 메타데이터를 처리하고 있습니다."]; const detail = eventDetail(update, fallback); const [icon, result] = toolStatus(update.status); card.className = `inline-tool-call is-${update.status}`; card.querySelector(".inline-tool-icon").textContent = icon; card.querySelector("strong").textContent = label; card.querySelector("small").textContent = detail; card.querySelector(".inline-tool-result").textContent = result; $("chat-scroll").scrollTop = $("chat-scroll").scrollHeight; }
async function streamReview(payload, onEvent) { const response = await fetch("/api/agent/review/stream", { method: "POST", headers: { "content-type": "application/json", accept: "text/event-stream" }, body: JSON.stringify(payload) }); if (!response.ok) { const result = await response.json(); throw new Error(`${result.error?.code || "ERROR"}: ${result.error?.message || "요청 실패"}`); } if (!response.body) throw new Error("STREAM_UNAVAILABLE: 브라우저가 응답 스트림을 제공하지 않습니다."); const reader = response.body.getReader(); const decoder = new TextDecoder(); let buffer = ""; const consume = () => { let boundary; while ((boundary = buffer.indexOf("\n\n")) >= 0) { const block = buffer.slice(0, boundary); buffer = buffer.slice(boundary + 2); if (!block.trim()) continue; let eventName = "message"; const data = []; for (const line of block.split("\n")) { if (line.startsWith("event:")) eventName = line.slice(6).trim(); if (line.startsWith("data:")) data.push(line.slice(5).trimStart()); } if (data.length) onEvent(eventName, JSON.parse(data.join("\n"))); } }; while (true) { const { value, done } = await reader.read(); buffer += decoder.decode(value || new Uint8Array(), { stream: !done }).replace(/\r\n/g, "\n"); consume(); if (done) break; } if (buffer.trim()) { buffer += "\n\n"; consume(); } }
function latestPlan(run) { return [...(run.events || [])].reverse().find((event) => event.type === "policy.plan_created")?.payload?.plan || null; }
function eventState(events) { const items = []; const toolIndexes = new Map(); for (const event of events || []) { if (event.type === "agent.evidence_round" || event.type === "agent.decision") { items.push({ ...event.payload, tool: event.type, status: "completed" }); continue; } if (!event.type.startsWith("tool.")) continue; const tool = event.payload?.tool; if (!tool) continue; let item = toolIndexes.has(tool) ? items[toolIndexes.get(tool)] : null; if (!item) { item = { tool, status: "running" }; toolIndexes.set(tool, items.length); items.push(item); } item.status = event.type === "tool.started" ? "running" : event.type === "tool.failed" ? "failed" : "completed"; item.code = event.payload?.code; } return items.slice(-10); }
function sourceTier(tier) { return tier === "korean_official" ? ["공공기관", "official"] : tier === "korean_research" ? ["국내 연구", "research"] : ["웹 후보", "web"]; }
function appendPlan(plan) { if (!plan || renderedPlanIds.has(plan.id) || (executionInProgress && !activeExecutionBody)) return; renderedPlanIds.add(plan.id); const assumptions = plan.assumptions || []; const rights = plan.rights_review; const node = document.createElement("section"); node.className = "policy-plan chat-message is-agent policy-review-message"; node.innerHTML = `<div class="chat-message-body"><h2>${escapeHtml(plan.policy_focus)} 정책 검토 플랜</h2><p class="policy-review-boundary">${escapeHtml(plan.target_population)}</p>${rights ? `<div class="plan-rights"><strong>권리·법률 선행 검토</strong><p>${escapeHtml(rights.finding)}</p>${(rights.issues || []).length ? `<ul>${rights.issues.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>` : ""}</div>` : ""}<h3>에이전트가 채택한 가정</h3><ul>${assumptions.length ? assumptions.map((item) => `<li><strong>${escapeHtml(item.field)}</strong> ${escapeHtml(item.value)} — ${escapeHtml(item.reason)}</li>`).join("") : "<li>추가 가정 없이 입력 범위를 사용합니다.</li>"}</ul><h3>같은 패널에서 비교할 정책안</h3><ul>${(plan.alternatives || []).map((item) => `<li><strong>${escapeHtml(item.label)}</strong> · ${escapeHtml(item.hypothesis)}</li>`).join("")}</ul></div>`; (activeExecutionBody || $("conversation")).append(node); $("chat-scroll").scrollTop = $("chat-scroll").scrollHeight; }
function renderSearchResults(result) { const seen = new Set(); const results = (result?.results || []).filter((item) => { const root = String(item.domain || "").replace(/^(www|stat|sso|ai|data)\./, ""); const key = `${root}|${item.query || item.title || item.url}`; if (!root || seen.has(key)) return false; seen.add(key); return true; }); if (!results.length) { searchSection().innerHTML = `<section class="source-result-group"><div class="source-result-heading"><span>검증 가능한 검색 후보 없음</span><span>근거 공백으로 기록하고 시나리오 검토를 계속했습니다.</span></div></section>`; return; } searchSection().innerHTML = `<section class="source-result-group"><div class="source-result-heading"><span>에이전트 병렬 탐색 · ${results.length}개 후보</span><span>스냅샷과 제외 사유는 Artifacts에 저장</span></div>${results.slice(0, 16).map((item) => { const [label, style] = sourceTier(item.trust_tier); const stripped = String(item.title || "").replace(/https?:\S+/g, " ").replace(/\s+/g, " ").trim(); const display = !stripped || stripped.length < 4 || stripped.includes("›") ? (item.query || item.domain || item.url) : stripped; return `<article class="source-search-row"><span class="source-icon">◈</span><div class="source-search-copy"><a href="${escapeHtml(item.url)}" target="_blank" rel="noreferrer">${escapeHtml(display)}</a><small>${escapeHtml(item.domain || item.url)}${item.query ? ` · ${escapeHtml(item.query)}` : ""}</small></div><span class="trust-chip ${style}">${label}</span></article>`; }).join("")}</section>`; }
function renderLedger(sources) { if (!sources?.length) { $("source-ledger").className = "inspector-empty"; $("source-ledger").textContent = "한국 공공기관·연구 출처를 기다리는 중"; return; } $("source-ledger").className = ""; $("source-ledger").innerHTML = sources.slice(0, 8).map((source) => `<article class="ledger-row"><i>◈</i><div><a href="${escapeHtml(source.url)}" target="_blank" rel="noreferrer">${escapeHtml(source.title)}</a><small>${escapeHtml(source.organization)} · ${escapeHtml(source.observed_period)} · ${(source.snapshot_hash || "").slice(0, 10)}</small></div></article>`).join(""); }
function notionistsAvatar(item) { const seed = item.avatar?.seed || "000000000000000000000000"; return { url: `/api/avatars/notionists/${encodeURIComponent(seed)}.svg`, alt: item.avatar?.alt || `${item.id}의 장식용 Notionists 합성 아바타` }; }
function renderPanel(result) { const tag = $("distribution-tag"), detail = $("distribution-detail"), panel = $("swarm-personas"); if (!result) { tag.textContent = "NOT ESTIMATED"; detail.textContent = "에이전트가 정량 근거를 검증합니다."; panel.textContent = "PGM 또는 시나리오 모델 뒤 생성됩니다."; return; } const scenario = result.status === "scenario_only"; tag.textContent = result.status === "feasible" ? "FEASIBLE · IPF" : scenario ? "SCENARIO ONLY" : String(result.status || "NOT ESTIMATED").toUpperCase(); detail.textContent = result.status === "feasible" || scenario ? `식별구간 ${result.identification?.lower ?? "?"}–${result.identification?.upper ?? "?"} · ${result.selected_model || "maximum_entropy"}` : "제약 충돌 또는 검토 필요"; const review = result.policy_review; const records = review?.panel || result.personas?.items?.map((item) => ({ ...item, weight_display: scenario ? "scenario" : "sampled" })) || []; panel.innerHTML = records.length ? records.slice(0, 8).map((item) => { const avatar = notionistsAvatar(item); return `<article class="panel-item"><span class="panel-avatar"><img src="${escapeHtml(avatar.url)}" alt="${escapeHtml(avatar.alt)}" loading="lazy" referrerpolicy="no-referrer"></span><span><strong>${escapeHtml(item.id)}</strong><small>${escapeHtml((item.attributes || []).map((attr) => `${attr.variable}:${attr.value_label || attr.value}`).join(" · "))}</small></span></article>`; }).join("") : "합성 프로필을 만들 수 없는 실행입니다."; }
function inlineMarkdown(text) { return escapeHtml(text).replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>").replace(/(^|[^*])\*([^*\s][^*]*)\*(?=[^*]|$)/g, "$1<em>$2</em>"); }
function markdownTableHtml(lines) { const rows = lines.map((line) => line.replace(/^\|/, "").replace(/\|$/, "").split("|").map((cell) => cell.trim())); const body = rows.filter((cells) => !cells.every((cell) => /^:?-{2,}:?$/.test(cell))); if (!body.length) return ""; const [head, ...rest] = body; return `<div class="brief-table-wrap"><table class="brief-table"><tr>${head.map((cell) => `<th>${inlineMarkdown(cell)}</th>`).join("")}</tr>${rest.map((cells) => `<tr>${cells.map((cell) => `<td>${inlineMarkdown(cell)}</td>`).join("")}</tr>`).join("")}</table></div>`; }
function formatBrief(brief) { const lines = String(brief || "").split("\n"); let html = ""; let listOpen = false; let sectionOpen = false; let tableLines = []; const flushTable = () => { if (tableLines.length) { html += markdownTableHtml(tableLines); tableLines = []; } }; const closeList = () => { if (listOpen) { html += "</ul>"; listOpen = false; } }; const closeSection = () => { flushTable(); closeList(); if (sectionOpen) { html += "</section>"; sectionOpen = false; } }; for (const line of lines) { if (line.trim().startsWith("|")) { closeList(); tableLines.push(line.trim()); continue; } flushTable(); if (line.startsWith("# ")) { closeSection(); continue; } if (line.startsWith("## ")) { closeSection(); html += `<section class="brief-section"><h3>${inlineMarkdown(line.slice(3))}</h3>`; sectionOpen = true; } else if (line.startsWith("### ")) { closeList(); html += `<h4 class="brief-subhead">${inlineMarkdown(line.slice(4))}</h4>`; } else if (line.startsWith("- ")) { if (!listOpen) { html += "<ul class=\"brief-list\">"; listOpen = true; } html += `<li>${inlineMarkdown(line.slice(2))}</li>`; } else if (line.startsWith("> ")) { closeList(); html += `<blockquote>${inlineMarkdown(line.slice(2))}</blockquote>`; } else if (line.trim()) { closeList(); html += `<p>${inlineMarkdown(line)}</p>`; } } closeSection(); return html; }
