function reviewMatrixHtml(review) { const panel = review.panel || []; const interviews = review.interviews || []; const alternatives = review.alternatives || []; if (!panel.length || !interviews.length || !alternatives.length) return ""; const byKey = new Map(interviews.map((item) => [`${item.segment_id}|${item.policy_id}`, item])); const header = `<tr><th>가상 인물</th>${alternatives.map((alt) => `<th>${escapeHtml(alt.label)}</th>`).join("")}</tr>`; const rows = panel.map((segment) => `<tr><th>${escapeHtml(personaName(segment))}</th>${alternatives.map((alt) => { const item = byKey.get(`${segment.id}|${alt.id}`); return `<td>${item ? `<span class="answer-badge is-${escapeHtml(item.response)}">${escapeHtml(RESPONSE_LABELS[item.response] || item.response)}</span>` : "–"}</td>`; }).join("")}</tr>`).join(""); const size = panel.length; const summary = `<tr class="matrix-summary"><th>표본 ${size}명 통계</th>${alternatives.map((alt) => { const counts = review.responses?.[alt.id] || {}; const parts = Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 2).map(([key, value]) => `${RESPONSE_LABELS[key] || key} ${Math.round(Number(value) * size)}명`).join(" · "); return `<td>${escapeHtml(parts || "–")}</td>`; }).join("")}</tr>`; return `<div class="review-matrix-wrap"><table class="review-matrix">${header}${rows}${summary}</table></div>`; }
