function responseChartHtml(review) { const interviews = review.interviews || []; const alternatives = review.alternatives || []; if (!interviews.length || !alternatives.length) return ""; const legend = RESPONSE_ORDER.map((key) => `<span><i style="background:${RESPONSE_COLORS[key]}"></i>${RESPONSE_LABELS[key]}</span>`).join(""); const rows = alternatives.map((alt) => { const counts = {}; interviews.filter((item) => item.policy_id === alt.id).forEach((item) => { counts[item.response] = (counts[item.response] || 0) + 1; }); const total = Object.values(counts).reduce((a, b) => a + b, 0) || 1; const summary = RESPONSE_ORDER.filter((key) => counts[key]).map((key) => `${RESPONSE_LABELS[key]} ${counts[key]}`).join(" · "); return `<div class="dist-row"><span class="dist-label">${escapeHtml(alt.label)}</span>${distBarHtml(counts, total)}<small>${escapeHtml(summary)}</small></div>`; }).join(""); return `<div class="dist-chart"><div class="dist-legend">${legend}</div>${rows}</div>`; }
function driverChartHtml(review) { const panel = review.panel || []; const interviews = review.interviews || []; const alternatives = review.alternatives || []; if (!panel.length || !interviews.length || !alternatives.length) return ""; const target = alternatives[0]; const byPersona = new Map(interviews.filter((item) => item.policy_id === target.id).map((item) => [item.segment_id, item.response])); const variables = [...new Set(panel.flatMap((segment) => (segment.attributes || []).map((attr) => attr.variable)))]; const blocks = variables.map((variable) => { const categories = new Map(); panel.forEach((segment) => { const attr = (segment.attributes || []).find((entry) => entry.variable === variable); const response = byPersona.get(segment.id); if (!attr || !response) return; const key = attr.value_label || attr.value; const bucket = categories.get(key) || {}; bucket[response] = (bucket[response] || 0) + 1; categories.set(key, bucket); }); if (categories.size < 2) return ""; const rows = [...categories.entries()].map(([value, counts]) => { const total = Object.values(counts).reduce((a, b) => a + b, 0) || 1; return `<div class="dist-row"><span class="dist-label">${escapeHtml(value)}</span>${distBarHtml(counts, total)}<small>${total}명</small></div>`; }).join(""); return `<div class="driver-block"><h4>${escapeHtml(variable.replaceAll("_", " "))}</h4>${rows}</div>`; }).filter(Boolean).join(""); return blocks ? `<div class="dist-chart driver-chart"><p class="driver-caption">${escapeHtml(target.label)} 기준 — 어떤 속성이 반응을 가르나</p>${blocks}</div>` : ""; }
function renderPolicyReview(result) { const review = result?.policy_review; if (!review) { const existing = document.getElementById("policy-review"); if (existing) existing.innerHTML = ""; return; } const matrix = reviewMatrixHtml(review); const omittedNote = review.omitted_cells?.length ? `<p class="evidence-note is-empty">표본 밖 소수 세그먼트 ${review.omitted_cells.length}개 — 좌석을 받지 못한 집단은 보고서 '표본 밖 세그먼트'와 사각지대 분석을 참조하세요.</p>` : ""; reviewSection().innerHTML = `<section class="chat-message is-agent policy-review-message"><div class="chat-message-body"><h2>가상 시민 패널 검토</h2><p class="policy-review-boundary">${escapeHtml(review.warning)}</p>${approvedConstraintsHtml()}${omittedNote}${responseChartHtml(review) ? `<h3>정책안별 반응 분포</h3>${responseChartHtml(review)}` : ""}${driverChartHtml(review)}${matrix ? `<details class="matrix-details"><summary>전체 응답 매트릭스 펼치기</summary>${matrix}</details>` : ""}${formatBrief(review.brief)}</div></section>`; }
function renderDownloads(downloads) { const labels = { html_report: ["종합 보고서", "HTML"], panel: ["합성 패널·응답", "JSONL"], interviews: ["모의 인터뷰", "JSONL"], evidence: ["증거·프로버넌스", "JSON"] }; const links = Object.entries(downloads || {}); const rows = links.map(([key, url]) => { const [title, format] = labels[key] || [key, "문서"]; return `<article class="artifact-file" data-artifact-url="${escapeHtml(url)}" data-artifact-label="${escapeHtml(title)}" role="button" tabindex="0"><span class="artifact-doc-icon" aria-hidden="true"><i></i></span><span class="artifact-file-copy"><strong>${escapeHtml(title)}</strong><small>문서 · ${escapeHtml(format)}</small></span><span class="artifact-file-actions"><button class="artifact-icon-button" type="button" data-artifact-download="${escapeHtml(url)}" aria-label="다운로드">⇩</button><button class="artifact-open-pill" type="button" data-artifact-url="${escapeHtml(url)}" data-artifact-label="${escapeHtml(title)}">열기</button></span></article>`; }).join(""); $("download-links").innerHTML = rows || "대화가 완료되면 브리프·패널·인터뷰·증거·보고서가 여기에 남습니다."; if (!rows) { document.getElementById("artifact-openers-block")?.remove(); return; } const node = ensureSection("artifact-openers-block", "artifact-openers", "artifact-openers"); node.setAttribute("aria-label", "정책 검토 산출물"); node.innerHTML = `<h3>산출물</h3><div class="artifact-files">${rows}</div>`; $("conversation").append(node); }
