function renderRun(run) { runId = run.id; currentRun = run; setEmptyState(false); knownRuns = [run, ...knownRuns.filter((item) => item.id !== run.id)].slice(0, 8); $("run-title").textContent = run.question || "새 정책 검토"; $("run-status").textContent = STATUS_LABELS[run.status] || run.status; $("inspector-status").textContent = `${run.sources.length}개 원문 · ${run.constraints.filter((item) => item.review_status === "approved").length}개 검증 제약`; $("detail-title").textContent = run.status === "completed" ? "최종 검토 결과" : "에이전트 작업 중"; $("detail-copy").textContent = run.question || "정책 검토를 준비하고 있습니다."; appendPlan(latestPlan(run)); renderLedger(run.sources); renderPanel(run.result); renderPolicyReview(run.result); renderPersonaFleet(run); renderProvenance(run.events); renderDownloads(artifactLinks(run)); renderStudyList(); if (activeDocumentKey === "personas") renderNativeDocument(documentTabs.get("personas")); }
const STATUS_LABELS = { planning: "자동 설계", researching: "근거 수집", waiting_for_review: "근거 수집", running: "PGM 실행", reviewed: "보고서 작성", completed: "검토 완료", safety_blocked: "안전 차단" };
function sidebarItems() { const chatRunIds = new Set(knownChats.map((chat) => chat.last_run_id).filter(Boolean)); const runItems = knownRuns.filter((run) => !chatRunIds.has(run.id)).map((run) => { const terminal = run.status === "completed" || run.status === "safety_blocked"; const activeNow = run.id === runId && executionInProgress; return { kind: "run", id: run.id, title: run.question || "정책 검토", subtitle: `${terminal || activeNow ? STATUS_LABELS[run.status] || run.status : "중단됨"} · ${run.target_population || ""}`, live: activeNow, active: run.id === runId, at: run.updated_at || run.created_at || "" }; }); const chatItems = knownChats.map((chat) => ({ kind: "chat", id: chat.session_id, title: chat.title || "대화", subtitle: `대화 · ${(chat.turns || []).length}턴${chat.last_run_id ? " · 검토 포함" : ""}`, live: false, active: chat.session_id === chatSessionId && !runId, at: chat.updated_at || "" })); return [...runItems, ...chatItems].sort((a, b) => String(b.at).localeCompare(String(a.at))); }
function renderStudyList() { const items = sidebarItems(); $("study-count").textContent = items.length; const filter = $("study-filter").value.toLowerCase(); const selected = items.filter((item) => item.title.toLowerCase().includes(filter)); $("study-list").className = ""; $("study-list").innerHTML = selected.length ? selected.map((item) => `<button class="study-row ${item.active ? "is-active" : ""}" type="button" ${item.kind === "run" ? `data-run-id="${escapeHtml(item.id)}"` : `data-chat-id="${escapeHtml(item.id)}"`}><span class="study-row-copy"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.subtitle)}</small></span>${item.live ? '<span class="study-row-live" aria-hidden="true"></span>' : ""}<span class="study-row-delete" role="button" tabindex="0" aria-label="세션 삭제" ${item.kind === "run" ? `data-delete-run="${escapeHtml(item.id)}"` : `data-delete-chat="${escapeHtml(item.id)}"`}>×</span></button>`).join("") : "<div class=\"study-filter-empty\">표시할 검토가 없습니다.</div>"; }
async function openChatSession(sessionId) { const data = await api(`/api/chats/${encodeURIComponent(sessionId)}`); const turns = data.turns || []; renderedPlanIds.clear(); personaPanelAutoOpened = true; $("conversation").innerHTML = ""; $("stream-tail").innerHTML = ""; runId = null; currentRun = null; chatSessionId = sessionId; try { localStorage.setItem("persona_chat_session", sessionId); } catch { /* private mode */ } setEmptyState(false); for (const turn of turns) message(turn.text, turn.role === "user" ? "user" : "agent"); if (data.last_run_id) { try { const run = await api(`/api/runs/${data.last_run_id}`); const candidates = run.result?.research?.candidates; if (Array.isArray(candidates) && candidates.length) renderSearchResults({ results: candidates }); renderRun(run); } catch { /* 삭제된 run이면 대화만 표시 */ } } $("run-title").textContent = (turns.find((turn) => turn.role === "user")?.text || "대화").slice(0, 60); if (!currentRun) $("run-status").textContent = "대화"; renderStudyList(); $("chat-scroll").scrollTop = 0; }
$("chat-form").addEventListener("submit", async (event) => { event.preventDefault(); if (executionInProgress) return; const text = $("chat-input").value.trim(); if (!text) return; setEmptyState(false); archiveRunSections(); personaPanelAutoOpened = false; message(text, "user"); if (attachedDoc) messageAttachment(attachedDoc); showThinking(); $("chat-input").value = ""; $("run-status").textContent = "에이전트 실행 중"; setSubmissionLocked(true); const toolCards = new Map(); let execution = null; const ensureExecution = () => { if (!execution) { execution = beginExecutionHistory(); activeExecutionBody = execution.body; } return execution; }; let activeStream = null; try { await streamReview({ text, event_id: crypto.randomUUID(), session_id: chatSessionId, ...(attachedDoc ? { attachment: attachedDoc } : {}) }, (name, data) => { if (["message.stream.start", "tool.update", "error"].includes(name)) removeThinking(); if (name === "message.accepted") { message(data.text, "agent"); showThinking(); } else if (name === "chat.accepted") { $("run-status").textContent = "에이전트 응답 중"; showThinking(); } else if (name === "chat.completed") { $("run-status").textContent = currentRun ? "검토 완료" : "대화"; setSubmissionLocked(false); api("/api/chats").then((chats) => { knownChats = chats.chats || []; renderStudyList(); }).catch(() => {}); } else if (name === "message.stream.start") { if (activeStream) finishStreamingMessage(activeStream); if (data.phase === "final") { if (execution) execution.history.open = false; activeStream = beginStreamingMessage($("conversation")); } else activeStream = beginStreamingMessage(ensureExecution().body); } else if (name === "message.delta" && activeStream) appendStreamingText(activeStream, data.delta); else if (name === "tool.update") appendToolUpdate(toolCards, data, ensureExecution().body); else if (name === "review.accepted" || name === "run.updated") renderRun(data.run); else if (name === "research.completed") renderSearchResults(data); else if (name === "review.completed") { renderRun(data.run); renderSearchResults(data.research); renderDownloads(data.artifacts); setSubmissionLocked(false); } else if (name === "error") throw new Error(`${data.code || "ERROR"}: ${data.message || "스트림 처리 실패"}`); }); } catch (error) { message(error.message, "system"); $("run-status").textContent = "실행 실패"; } finally { removeThinking(); clearAttachment(); if (activeStream) finishStreamingMessage(activeStream); activeExecutionBody = null; setSubmissionLocked(false); } });
(async () => { try { const [runsData, chatsData] = await Promise.all([api("/api/runs").catch(() => ({})), api("/api/chats").catch(() => ({}))]); if (Array.isArray(runsData.runs)) knownRuns = runsData.runs.slice(0, 8); if (Array.isArray(chatsData.chats)) knownChats = chatsData.chats.slice(0, 8); renderStudyList(); const current = knownChats.find((chat) => chat.session_id === chatSessionId); if (current?.turns?.length && $("conversation").childElementCount === 0 && !executionInProgress) await openChatSession(chatSessionId); } catch { /* 저장된 세션이 없으면 조용히 넘어간다 */ } })();

function loadRun(run) { renderedPlanIds.clear(); personaPanelAutoOpened = true; $("conversation").innerHTML = ""; $("stream-tail").innerHTML = ""; setEmptyState(false); if (run.question) message(run.question, "user"); const candidates = run.result?.research?.candidates; if (Array.isArray(candidates) && candidates.length) renderSearchResults({ results: candidates }); renderRun(run); $("chat-scroll").scrollTop = 0; }
document.addEventListener("click", async (event) => { const deleteButton = event.target.closest("[data-delete-run]"); if (deleteButton) { if (executionInProgress) return; const id = deleteButton.dataset.deleteRun; try { await api(`/api/runs/${id}`, "DELETE"); knownRuns = knownRuns.filter((run) => run.id !== id); if (runId === id) resetWorkspace(); else renderStudyList(); } catch (error) { message(error.message, "system"); } return; } const deleteChat = event.target.closest("[data-delete-chat]"); if (deleteChat) { if (executionInProgress) return; const id = deleteChat.dataset.deleteChat; try { await api(`/api/chats/${encodeURIComponent(id)}`, "DELETE"); knownChats = knownChats.filter((chat) => chat.session_id !== id); if (chatSessionId === id) resetWorkspace(); else renderStudyList(); } catch (error) { message(error.message, "system"); } return; } const chatButton = event.target.closest("[data-chat-id]"); if (chatButton) { if (executionInProgress) return; try { await openChatSession(chatButton.dataset.chatId); } catch (error) { message(error.message, "system"); } return; } const runButton = event.target.closest("[data-run-id]"); if (runButton) { if (executionInProgress) return; try { loadRun(await api(`/api/runs/${runButton.dataset.runId}`)); } catch (error) { message(error.message, "system"); } return; } const trigger = event.target.closest("[data-action]"); if (trigger?.dataset.action === "toggle-sidebar") { setSidebarCollapsed(!document.querySelector(".workbench-shell").classList.contains("is-sidebar-collapsed")); return; } if (trigger?.dataset.action === "new-policy") resetWorkspace(); });
$("chat-input").addEventListener("keydown", (event) => { if (event.key !== "Enter" || event.shiftKey || event.isComposing) return; event.preventDefault(); if (executionInProgress || event.currentTarget.disabled) return; $("chat-form").requestSubmit(); });
$("study-filter").addEventListener("input", renderStudyList);
document.querySelectorAll("[data-scroll]").forEach((button) => button.addEventListener("click", () => $(button.dataset.scroll).scrollIntoView({ behavior: "smooth", block: "start" })));
document.addEventListener("click", (event) => { const tab = event.target.closest("[data-document-tab]"); if (tab) { activateDocumentTab(tab.dataset.documentTab); return; } const personaRow = event.target.closest("[data-persona-id]"); if (personaRow) { openPersonaPanel(personaRow.dataset.personaId); return; } if (event.target.closest("[data-document-download]")) { const active = documentTabs.get(activeDocumentKey); if (active?.url) window.open(active.url, "_blank"); return; } if (event.target.closest("[data-document-close]")) setDrawerOpen(false); });
document.addEventListener("keydown", (event) => { if (event.key === "Escape" && $("document-drawer").classList.contains("is-open")) setDrawerOpen(false); });
document.querySelector("[data-document-resizer]")?.addEventListener("pointerdown", (event) => { const drawer = $("document-drawer"); if (!drawer.classList.contains("is-open")) return; event.preventDefault(); const resizer = event.currentTarget; resizer.setPointerCapture(event.pointerId); drawer.classList.add("is-resizing"); const startX = event.clientX; const startWidth = drawer.getBoundingClientRect().width; const onMove = (move) => { const width = Math.min(Math.max(startWidth + (startX - move.clientX), 360), Math.round(window.innerWidth * 0.8)); drawer.style.setProperty("--drawer-width", `${width}px`); }; const onUp = () => { drawer.classList.remove("is-resizing"); resizer.removeEventListener("pointermove", onMove); resizer.removeEventListener("pointerup", onUp); resizer.removeEventListener("pointercancel", onUp); }; resizer.addEventListener("pointermove", onMove); resizer.addEventListener("pointerup", onUp); resizer.addEventListener("pointercancel", onUp); });
document.addEventListener("click", (event) => { const download = event.target.closest("[data-artifact-download]"); if (download) { window.open(download.dataset.artifactDownload, "_blank"); return; } const artifact = event.target.closest("[data-artifact-url]"); if (!artifact) return; event.preventDefault(); openDocument(artifact.dataset.artifactLabel, artifact.dataset.artifactUrl); });
